    correction: [{"quoi":"القاعدة","math":"نضع أصغر قوّة عاملا مشتركا، فيبقى داخل القوس عدد صغير"},{"quoi":"نوحّد الأساس","math":"<span dir=\"ltr\" class=\"expr\">49<sup>53</sup> = 7<sup>106</sup></span>"},{"quoi":"نُظهر العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">7<sup>106</sup> = 7<sup>105</sup> × 7</span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">7<sup>105</sup> + 7<sup>106</sup> = 7<sup>105</sup>(1 + 7)</span>"},{"quoi":"نحسب داخل القوس","math":"<span dir=\"ltr\" class=\"expr\">1 + 7 = 8</span>"},{"quoi":"نكتب الجداء","math":"<span dir=\"ltr\" class=\"expr\">7<sup>105</sup> + 49<sup>53</sup> = 8 × 7<sup>105</sup></span>"},{"quoi":"نُظهر القاسم 196","math":"<span dir=\"ltr\" class=\"expr\">8 × 7<sup>105</sup> = 196 × (2 × 7<sup>103</sup></span>"},{"quoi":"النتيجة","math":"العدد يساوي <span dir=\"ltr\" class=\"expr\">196 × 2 × 7<sup>103</sup></span> و منه يقبل القسمة على 196"}],
