    correction: [{"quoi":"القاعدة","math":"لا يمكن جمع قوّتين إلاّ إذا كان لهما نفس الأساس"},{"quoi":"نوحّد الأساس في الحدّ الأوّل","math":"<span dir=\"ltr\" class=\"expr\">125<sup>53</sup> = 5<sup>159</sup></span>"},{"quoi":"نعيد كتابة العدد","math":"<span dir=\"ltr\" class=\"expr\">7 × 125<sup>53</sup> - 5<sup>160</sup> = 7 × 5<sup>159</sup> - 5<sup>160</sup></span>"},{"quoi":"نُخرج أصغر قوّة","math":"<span dir=\"ltr\" class=\"expr\">7 × 5<sup>159</sup> - 5<sup>160</sup> = 5<sup>159</sup>(7 - 5)</span>"},{"quoi":"نحسب داخل القوس","math":"<span dir=\"ltr\" class=\"expr\">7 - 5 = 2</span>"},{"quoi":"نكتب الجداء","math":"<span dir=\"ltr\" class=\"expr\">7 × 125<sup>53</sup> - 5<sup>160</sup> = 2 × 5<sup>159</sup></span>"},{"quoi":"نُظهر القاسم 50","math":"<span dir=\"ltr\" class=\"expr\">2 × 5<sup>159</sup> = 50 × 5<sup>157</sup></span>"},{"quoi":"النتيجة","math":"العدد يساوي <span dir=\"ltr\" class=\"expr\">50 × 5<sup>157</sup></span> و منه يقبل القسمة على 50"}],
