    correction: [{"quoi":"القاعدة","math":"نوحّد الأساس ثمّ نضع أصغر قوّة عاملا مشتركا"},{"quoi":"نوحّد الأساس في الحدّ الثاني","math":"<span dir=\"ltr\" class=\"expr\">25<sup>777</sup> = 5<sup>1554</sup></span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">5<sup>1556</sup> + n × 5<sup>1554</sup> = 5<sup>1554</sup>(5<sup>2</sup> + n)</span>"},{"quoi":"نفكّك القاسم","math":"<span dir=\"ltr\" class=\"expr\">150 = 25 × 6</span>"},{"quoi":"العامل 25 موجود دائما","math":"<span dir=\"ltr\" class=\"expr\">5<sup>1554</sup> = 5<sup>2</sup> × 5<sup>1552</sup></span>"},{"quoi":"يبقى الشرط على 6","math":"بما أنّ 6 و 5 أوليان فيما بينهما، يجب أن يقبل <span dir=\"ltr\" class=\"expr\">5<sup>2</sup> + n</span> القسمة على 6"},{"quoi":"نحسب الحدّ الثابت","math":"<span dir=\"ltr\" class=\"expr\">5<sup>2</sup> = 25</span>"},{"quoi":"نبحث عن n","math":"نبحث عن n أصغر من 50 بحيث يقبل <span dir=\"ltr\" class=\"expr\">25 + n</span> القسمة على 6"},{"quoi":"النتيجة","math":"القيم الممكنة لـ n هي<span dir=\"ltr\" class=\"expr\">: 5 ؛ 11 ؛ 17 ؛ 23 ؛ 29 ؛ 35 ؛ 41 ؛ 47</span>"}],
