    enonce: "ليكن n عددا صحيحا طبيعيا أصغر من 50 و لتكن <span dir=\"ltr\" class=\"expr\">E = 2<sup>810</sup> + n × 8<sup>269</sup></span> أوجد كلّ القيم الممكنة لـ n لتقبل E القسمة على 26",
    correction: [{"quoi":"القاعدة","math":"نوحّد الأساس ثمّ نضع أصغر قوّة عاملا مشتركا"},{"quoi":"نوحّد الأساس في الحدّ الثاني","math":"<span dir=\"ltr\" class=\"expr\">8<sup>269</sup> = 2<sup>807</sup></span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">2<sup>810</sup> + n × 2<sup>807</sup> = 2<sup>807</sup>(2<sup>3</sup> + n)</span>"},{"quoi":"نفكّك القاسم","math":"<span dir=\"ltr\" class=\"expr\">26 = 2 × 13</span>"},{"quoi":"العامل 2 موجود دائما","math":"<span dir=\"ltr\" class=\"expr\">2<sup>807</sup> = 2 × 2<sup>806</sup></span>"},{"quoi":"يبقى الشرط على 13","math":"بما أنّ 13 و 2 أوليان فيما بينهما، يجب أن يقبل <span dir=\"ltr\" class=\"expr\">2<sup>3</sup> + n</span> القسمة على 13"},{"quoi":"نحسب الحدّ الثابت","math":"<span dir=\"ltr\" class=\"expr\">2<sup>3</sup> = 8</span>"},{"quoi":"نبحث عن n","math":"نبحث عن n أصغر من 50 بحيث يقبل <span dir=\"ltr\" class=\"expr\">8 + n</span> القسمة على 13"},{"quoi":"النتيجة","math":"القيم الممكنة لـ n هي<span dir=\"ltr\" class=\"expr\">: 5 ؛ 18 ؛ 31 ؛ 44</span>"}],
