    enonce: "ليكن n عددا صحيحا طبيعيا أصغر من 30 و لتكن <span dir=\"ltr\" class=\"expr\">E = 2<sup>1703</sup> + n × 2<sup>1700</sup></span> أوجد كلّ القيم الممكنة لـ n لتقبل E القسمة على 20",
    correction: [{"quoi":"القاعدة","math":"نوحّد الأساس ثمّ نضع أصغر قوّة عاملا مشتركا"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">2<sup>1703</sup> + n × 2<sup>1700</sup> = 2<sup>1700</sup>(2<sup>3</sup> + n)</span>"},{"quoi":"نفكّك القاسم","math":"<span dir=\"ltr\" class=\"expr\">20 = 4 × 5</span>"},{"quoi":"العامل 4 موجود دائما","math":"<span dir=\"ltr\" class=\"expr\">2<sup>1700</sup> = 2<sup>2</sup> × 2<sup>1698</sup></span>"},{"quoi":"يبقى الشرط على 5","math":"بما أنّ 5 و 2 أوليان فيما بينهما، يجب أن يقبل <span dir=\"ltr\" class=\"expr\">2<sup>3</sup> + n</span> القسمة على 5"},{"quoi":"نحسب الحدّ الثابت","math":"<span dir=\"ltr\" class=\"expr\">2<sup>3</sup> = 8</span>"},{"quoi":"نبحث عن n","math":"نبحث عن n أصغر من 30 بحيث يقبل <span dir=\"ltr\" class=\"expr\">8 + n</span> القسمة على 5"},{"quoi":"النتيجة","math":"القيم الممكنة لـ n هي<span dir=\"ltr\" class=\"expr\">: 2 ؛ 7 ؛ 12 ؛ 17 ؛ 22 ؛ 27</span>"}],
